"""Re-derive every reported value from the input + the output itself."""
import json, sys

def check(doc, out):
    cfg = doc["config"]; mdl = doc["model"]
    C = mdl["classes"]; W = cfg["window"]; S = cfg["slots"]
    idle = cfg["idle_timeout"]; lq = cfg["len_quantum"]; gq = cfg["gap_quantum"]
    rn = cfg["rate_num"]; rd = cfg["rate_den"]; bc = cfg["bucket_capacity"]
    it = cfg["initial_tokens"]; pcap = cfg["pending_capacity"]; L = cfg["lanes"]
    svc = cfg["service"]; fb = cfg["fallback"]; te = cfg["time_edges"]; ce = cfg["count_edges"]
    pr = cfg["probability"]
    errs = []
    pk = doc["packets"]; conns = doc["connections"]
    idset = [c["id"] for c in conns]
    slotof = {c["id"]: c["slot"] for c in conns}
    opk = out["packets"]; oj = out["jobs"]; ocon = out["connections"]

    def fail(msg):
        errs.append(msg)

    # --- structural ---
    if len(opk) != len(pk): fail("packet count")
    if [p["index"] for p in opk] != list(range(len(pk))): fail("packet index order")
    for i,(p,q) in enumerate(zip(opk,pk)):
        if p["connection"] != q["connection"]: fail("packet conn %d"%i)
    if [j["id"] for j in oj] != list(range(len(oj))): fail("job id order")

    # --- replay-lite using reported predictions for scheduling ---
    gen = [0]*S
    occ = [None]*S
    lastpt = [0]*S
    win = [[] for _ in range(S)]
    cls = [None]*S
    lastap = [-1]*S
    anchor = [0]*S
    backlog = [0]*S
    avail = [0]*L
    credit = it*rd
    lastref = 0
    cap = bc*rd
    pend = {}      # id -> (done, slot, conn, gen, pred)
    votes = {c["id"]: [0]*C for c in conns}
    cnt = {c["id"]: 0 for c in conns}
    jobs = []
    for i in range(len(pk)):
        t = pk[i]["time"]; cid = pk[i]["connection"]; ln = pk[i]["length"]; draw = pk[i]["draw"]
        rep = opk[i]
        # completions
        ready = sorted([j for j in pend if pend[j][0] <= t], key=lambda j:(pend[j][0], j))
        status = {}
        for j in ready:
            done, s, jc, jg, jp = pend.pop(j)
            if occ[s] is None or occ[s] != jc or gen[s] != jg: status[j] = "stale"
            elif j <= lastap[s]: status[j] = "superseded"
            else:
                status[j] = "applied"; cls[s] = jp; lastap[s] = j
        for j in ready:
            if oj[j]["status"] != status[j]: fail("job %d status %s != %s"%(j, oj[j]["status"], status[j]))
        # refill
        credit = min(cap, credit + (t-lastref)*rn); lastref = t
        s = slotof[cid]
        if occ[s] is None or occ[s] != cid or t - lastpt[s] >= idle:
            gen[s] += 1; occ[s] = cid; win[s] = []; cls[s] = None; lastap[s] = -1
            anchor[s] = t; backlog[s] = 0; gap = 0
        else:
            gap = t - lastpt[s]
        lastpt[s] = t
        row = [min(15, ln//lq), min(15, gap//gq)]
        win[s].append(row); win[s] = win[s][-W:]
        backlog[s] += 1
        fwd = cls[s] if cls[s] is not None else fb
        votes[cid][fwd] += 1; cnt[cid] += 1
        if rep["generation"] != gen[s]: fail("packet %d gen"%i)
        if rep["forward"] != fwd: fail("packet %d forward"%i)
        if rep["credit"] != credit: fail("packet %d credit %d != %d"%(i, rep["credit"], credit))
        # decision
        if len(win[s]) < W: dec = "warmup"; jid = None
        else:
            Ti = t - anchor[s]; Ci = backlog[s]
            ti = max(k for k,e in enumerate(te) if e <= Ti)
            cj = max(k for k,e in enumerate(ce) if e <= Ci)
            p = pr[ti][cj]
            if draw >= p: dec = "probability"; jid=None
            elif credit < rd: dec = "tokens"; jid=None
            elif len(pend) >= pcap: dec = "queue"; jid=None
            else:
                dec = "sent"; credit -= rd
                # lane choice using reported predictions: prediction must be consistent with window
                jid = len(jobs)
                # find reported job to get prediction
                rep_pred = None
                lane = 0; lt = avail[0]
                for li in range(1, L):
                    if avail[li] < lt: lt = avail[li]; lane = li
                start = max(t, lt)
                # we need the prediction: use the reported job record later
                jobs.append((jid, i, cid, s, gen[s], lane, start, t, win[s][:]))
                avail[lane] = None  # placeholder, fixed below
                avail[lane] = lt  # will be corrected after we know done
                anchor[s] = t; backlog[s] = 0
        if rep["decision"] != dec: fail("packet %d decision %s != %s"%(i, rep["decision"], dec))
        if rep["job"] != jid: fail("packet %d job %r != %r"%(i, rep["job"], jid))

    # --- job records: windows, lane, start, done ---
    if len(oj) != len(jobs): fail("job count %d != %d"%(len(oj), len(jobs)))
    avail = [0]*L
    for (jid, i, cid, s, g, lane, start, t, w) in jobs:
        j = oj[jid]
        if j["packet"] != i: fail("job %d packet"%jid)
        if j["connection"] != cid: fail("job %d conn"%jid)
        if j["slot"] != s: fail("job %d slot"%jid)
        if j["generation"] != g: fail("job %d gen"%jid)
        if j["window"] != w: fail("job %d window %r != %r"%(jid, j["window"], w))
        # lane choice depends on service which depends on prediction -> recompute using reported prediction
        lt = avail[0]; lane2 = 0
        for li in range(1, L):
            if avail[li] < lt: lt = avail[li]; lane2 = li
        if j["lane"] != lane2: fail("job %d lane %d != %d"%(jid, j["lane"], lane2))
        if j["start"] != max(t, lt): fail("job %d start"%jid)
        if j["done"] != j["start"] + svc[j["prediction"]]: fail("job %d done"%jid)
        avail[lane2] = j["done"]

    # --- connections ---
    if len(ocon) != len(conns): fail("conn count")
    for i, c in enumerate(conns):
        o = ocon[i]
        if o["id"] != c["id"]: fail("conn order")
        if o["split"] != c["split"] or o["label"] != c["label"]: fail("conn meta %s"%c["id"])
        if o["packets"] != cnt[c["id"]]: fail("conn packets %s"%c["id"])
        if o["votes"] != votes[c["id"]]: fail("conn votes %s: %r != %r"%(c["id"], o["votes"], votes[c["id"]]))
        if cnt[c["id"]] == 0:
            if o["prediction"] is not None: fail("conn pred null %s"%c["id"])
        else:
            m = max(votes[c["id"]])
            if o["prediction"] != votes[c["id"]].index(m): fail("conn pred %s"%c["id"])
    # --- reports ---
    conf = {"dev": [[0]*C for _ in range(C)], "eval": [[0]*C for _ in range(C)]}
    obs = {"dev":0, "eval":0}
    for i, c in enumerate(conns):
        if cnt[c["id"]] == 0: continue
        obs[c["split"]] += 1
        conf[c["split"]][c["label"]][ocon[i]["prediction"]] += 1
    for sp in ("dev","eval"):
        r = out["reports"][sp]
        if r["connections"] != obs[sp]: fail("report %s connections"%sp)
        if r["confusion"] != conf[sp]: fail("report %s confusion"%sp)
        from fractions import Fraction
        fs = []
        for c in range(C):
            tp = conf[sp][c][c]
            fp = sum(conf[sp][rr][c] for rr in range(C)) - tp
            fn = sum(conf[sp][c]) - tp
            d = 2*tp+fp+fn
            fs.append(Fraction(2*tp, d) if d else Fraction(0))
        mf = sum(fs)/C
        if r["macro_f1"] != [mf.numerator, mf.denominator]: fail("report %s macro_f1 %r != %r"%(sp, r["macro_f1"], [mf.numerator, mf.denominator]))
    return errs

if __name__ == "__main__":
    doc = json.load(open(sys.argv[1]))
    out = json.load(open(sys.argv[2]))
    errs = check(doc, out)
    print("errors:", len(errs))
    for e in errs[:20]: print("  ", e)
